import {
  controls, openRegistration, resetRegistration, uniqueRegistration,
  fillRegistration, submitRegistration, successFeedback, errorSummary,
  expectFieldError, expectFirstInvalid, expectRejection, storageCorpus,
} from './course-gui-test-support.js';

const VALID_PASSWORD = 'Password01';

function rgb(el: { evaluate: (fn: (e: HTMLElement) => string) => Promise<string> }) {
  return el.evaluate((e) => getComputedStyle(e).color);
}

function channels(c: string) {
  const m = c.match(/\d+/g)!;
  return m.slice(0, 3).map(Number);
}

test.describe('registration', () => {
  test('accessible structure', async ({ page }) => {
    await openRegistration(page);
    const c = controls(page);
    await expect(c.heading).toHaveText(/register|create.*account|sign up/i);
    await expect(c.form).toBeVisible();
    await expect(c.username).toHaveAccessibleName(/username/i);
    await expect(c.email).toHaveAccessibleName(/email/i);
    await expect(c.password).toHaveAccessibleName(/password/i);
    await expect(c.confirmPassword).toHaveAccessibleName(/confirm/i);
    await expect(c.terms).toHaveAccessibleName(/terms/i);
    await expect(c.submit).toHaveAccessibleName(/register|create|sign up|submit/i);
    await expect(c.email).toHaveAttribute('type', 'email');
    await expect(c.password).toHaveAttribute('type', 'password');
    await expect(c.confirmPassword).toHaveAttribute('type', 'password');
    await expect(c.username).toHaveAttribute('autocomplete', /username/i);
    await expect(c.email).toHaveAttribute('autocomplete', /email/i);
    await expect(c.password).toHaveAttribute('autocomplete', /new-password/i);
    await expect(c.dateOfBirth).toHaveAttribute('type', 'date');
  });

  test('empty submission reports all problems, summary, and focus', async ({ page }) => {
    await resetRegistration(page);
    await openRegistration(page);
    const c = controls(page);
    await fillRegistration(page, { terms: false });
    await c.username.fill('');
    await c.email.fill('');
    await c.password.fill('');
    await c.confirmPassword.fill('');
    await submitRegistration(page);
    await expect(errorSummary(page)).toBeVisible();
    await expectFieldError(page, 'username');
    await expectFieldError(page, 'email');
    await expectFieldError(page, 'password');
    await expectFieldError(page, 'confirmPassword');
    await expectFieldError(page, 'terms');
    await expectFirstInvalid(page, 'username');
    for (const f of [c.username, c.email, c.password, c.confirmPassword]) {
      const desc = await f.getAttribute('aria-describedby');
      expect(desc, 'invalid control should reference its explanation').toBeTruthy();
    }
  });

  test('corrected submission clears stale errors and succeeds', async ({ page }) => {
    await resetRegistration(page);
    await openRegistration(page);
    const c = controls(page);
    await fillRegistration(page, { terms: false });
    await submitRegistration(page);
    await expect(errorSummary(page)).toBeVisible();
    await fillRegistration(page, { password: VALID_PASSWORD });
    await submitRegistration(page);
    await expect(successFeedback(page)).toBeVisible();
    await expect(errorSummary(page)).toHaveCount(0);
    await expectFieldError(page, 'terms', /^$/);
  });

  test('field policy boundaries', async ({ page }) => {
    await resetRegistration(page);
    await openRegistration(page);
    const c = controls(page);
    const rows: Array<{ name: string; apply: () => Promise<void>; field: Parameters<typeof expectFieldError>[1]; pattern?: RegExp }> = [
      {
        name: 'username too short after trim',
        apply: async () => { await fillRegistration(page, { username: '  Ab  ' }); },
        field: 'username',
      },
      {
        name: 'username 20 chars valid',
        apply: async () => {
          await fillRegistration(page, { username: 'Ab3'.padEnd(20, '_'), email: uniqueRegistration().email });
          await submitRegistration(page);
          await expect(successFeedback(page)).toBeVisible();
        },
        field: 'username',
      },
      {
        name: 'username 21 chars invalid',
        apply: async () => {
          await fillRegistration(page, { username: 'Ab3'.padEnd(21, '_'), email: uniqueRegistration().email });
          await submitRegistration(page);
        },
        field: 'username',
      },
      {
        name: 'username must start with letter',
        apply: async () => { await fillRegistration(page, { username: '1abc', email: uniqueRegistration().email }); },
        field: 'username',
      },
      {
        name: 'email missing domain',
        apply: async () => { await fillRegistration(page, { email: 'user@' }); },
        field: 'email',
      },
      {
        name: 'email repeated dots',
        apply: async () => { await fillRegistration(page, { email: 'a..b@example.com' }); },
        field: 'email',
      },
      {
        name: 'email dot-bounded local part',
        apply: async () => { await fillRegistration(page, { email: '.abc@example.com' }); },
        field: 'email',
      },
      {
        name: 'email hyphen-bounded label',
        apply: async () => { await fillRegistration(page, { email: 'abc@-example.com' }); },
        field: 'email',
      },
      {
        name: 'email one-letter final label valid',
        apply: async () => {
          await fillRegistration(page, { email: uniqueRegistration().username.toLowerCase() + '@example.a' });
          await submitRegistration(page);
          await expect(successFeedback(page)).toBeVisible();
        },
        field: 'email',
      },
      {
        name: 'password 9 chars invalid',
        apply: async () => { await fillRegistration(page, { password: 'Abcdefgh1' }); },
        field: 'password',
      },
      {
        name: 'password 10 chars valid',
        apply: async () => {
          await fillRegistration(page, { password: 'Abcdefghi1', email: uniqueRegistration().email });
          await submitRegistration(page);
          await expect(successFeedback(page)).toBeVisible();
        },
        field: 'password',
      },
      {
        name: 'password 64 chars valid',
        apply: async () => {
          await fillRegistration(page, { password: 'A1' + 'x'.repeat(62), email: uniqueRegistration().email });
          await submitRegistration(page);
          await expect(successFeedback(page)).toBeVisible();
        },
        field: 'password',
      },
      {
        name: 'password 65 chars invalid',
        apply: async () => { await fillRegistration(page, { password: 'A1' + 'x'.repeat(63) }); },
        field: 'password',
      },
      {
        name: 'password letters only invalid',
        apply: async () => { await fillRegistration(page, { password: 'abcdefghij' }); },
        field: 'password',
      },
      {
        name: 'password uppercase-only with digit valid',
        apply: async () => {
          await fillRegistration(page, { password: 'ABCDEFGHI1', email: uniqueRegistration().email });
          await submitRegistration(page);
          await expect(successFeedback(page)).toBeVisible();
        },
        field: 'password',
      },
      {
        name: 'confirmation mismatch owned by confirm field',
        apply: async () => {
          await fillRegistration(page, { password: VALID_PASSWORD, confirmPassword: 'Password02' });
        },
        field: 'confirmPassword',
      },
      {
        name: 'missing terms rejected',
        apply: async () => { await fillRegistration(page, { terms: false }); },
        field: 'terms',
      },
      {
        name: 'real date accepted',
        apply: async () => {
          await fillRegistration(page, { dateOfBirth: '2000-02-29', email: uniqueRegistration().email });
          await submitRegistration(page);
          await expect(successFeedback(page)).toBeVisible();
        },
        field: 'dateOfBirth',
      },
    ];
    for (const row of rows) {
      await row.apply();
      if (row.name.includes('valid') || row.name.includes('accepted')) {
        if (!row.name.includes('valid') || !row.name.includes('chars valid')) {
          // success already asserted inside apply for success rows
        }
      } else {
        await expectRejection(page);
        await expectFieldError(page, row.field);
      }
    }
  });

  test('password show/hide toggles both fields and accessible name', async ({ page }) => {
    await resetRegistration(page);
    await openRegistration(page);
    const c = controls(page);
    await fillRegistration(page, { password: VALID_PASSWORD });
    const before = await c.password.getAttribute('type');
    expect(before).toBe('password');
    const nameBefore = await c.passwordToggle.accessibleName();
    await c.passwordToggle.click();
    expect(await c.password.getAttribute('type')).toBe('text');
    expect(await c.confirmPassword.getAttribute('type')).toBe('text');
    const nameAfter = await c.passwordToggle.accessibleName();
    expect(nameAfter.toLowerCase()).not.toBe(nameBefore.toLowerCase());
    await c.passwordToggle.click();
    expect(await c.password.getAttribute('type')).toBe('password');
    expect(await c.confirmPassword.getAttribute('type')).toBe('password');
  });

  test('persistence: trimmed username, lowercased email, duplicates across reload, no password stored', async ({ page }) => {
    await resetRegistration(page);
    await openRegistration(page);
    const id = uniqueRegistration();
